column4:
 ```js
const map = new maplibregl.Map({
  container: 'map',
  style: 'https://demotiles.maplibre.org/style.json',
  center: [lon, lat],
  zoom: 10
});
map.addSource('parcels', {
  type: 'vector',
  url: 'http://your-server/tiles/{z}/{x}/{y}.pbf'
});
map.addLayer({
  id: 'parcels-fill',
  type: 'fill',
  source: 'parcels',
  'source-layer': 'parcels',
  paint: { 'fill-color': '#088', 'fill-opacity': 0.4 }
});
```
